def verdict(text: str) -> str:
    result = jenkins.analyze("Jenkinsfile", textwrap.dedent(text).encode(), load(), None)
    severities = {f.severity for f in result.findings if f.rule == "OBAAF-JEN-012"}
    if severities:
        return "finding-high" if "high" in severities else "finding-medium"
    row = next((row for row in jenkins.coverage(result, result.findings) if row["rule"] == "OBAAF-JEN-012"), None)
    if row is None or row["status"] in ("pass", "not applicable"):
        return "quiet"
    return "unknown" if row["status"] == "unknown" else row["status"]


class ProvenanceCheckBypassTest(unittest.TestCase):
    def test_every_attempt(self):
        for name, expected, _before, text in CASES:
            with self.subTest(case=name):
                self.assertEqual(verdict(text), expected)

    def test_limits_name_real_cases_whose_answer_differs(self):
        answers = {c[0]: c[1] for c in CASES}
        self.assertLessEqual(set(LIMITS), set(answers))
        for name, (judged, _why) in LIMITS.items():
            self.assertNotEqual(answers[name], judged, name)

    def test_no_way_past_is_left(self):
        # A finding the attacker judged right is never quiet now, and nothing judged cannot tell is quiet.
        for name, (judged, _why) in LIMITS.items():
            with self.subTest(case=name):
                self.assertFalse(judged != "quiet" and dict((c[0], c[1]) for c in CASES)[name] == "quiet")

    def test_no_attempt_is_slow(self):
        for name, _expected, _before, text in CASES:
            started = time.monotonic()
            verdict(text)
            with self.subTest(case=name):
                self.assertLess(time.monotonic() - started, 3.0)

    def test_old_messages_kept_for_a_baseline(self):
        unchecked = "node {\n  sh 'docker push registry.example.com/app:1.0'\n}\n"
        provenance = ("node {\n  sh 'cosign verify-attestation --type slsaprovenance img'\n"
                      "  sh 'docker push registry.example.com/app:1.0'\n}\n")
        messages = []
        for text in (unchecked, provenance):
            result = jenkins.analyze("Jenkinsfile", text.encode(), load(), None)
            messages += [f.message for f in result.findings if f.rule == "OBAAF-JEN-012"]
        self.assertEqual(messages, [
            "The step at line 2 publishes (docker push) without an earlier check that stops the build when "
            "verification fails.",
            "The step at line 3 publishes after a provenance check only; approvals and agent records are not checked "
            "(use obaaf verify release)."])


if __name__ == "__main__":
    unittest.main()
